import numpy as npfrom scipy.optimize import curve_fitfrom astropy.io import fitsimport osimport pandas as pdresults = []base_dir = "data/organized_spectra"for target in os.listdir(base_dir):    target_path = os.path.join(base_dir, target)    if not os.path.isdir(target_path):        continue    for file in os.listdir(target_path):        if file.endswith(".fits"):            filepath = os.path.join(target_path, file)            print("Processing:", filepath)            hdul = fits.open(filepath)            data = hdul[0].data            data = np.squeeze(data)        # Handle weird multi-layer spectra            if len(data.shape) > 2:                data = data[0]            flux_orders = data            # Skip spectra with too few orders            flux_orders = data# skip spectra that are not 2-D echelle spectra            if len(flux_orders.shape) < 2:                print("Skipping spectrum (not an echelle spectrum)")                continue# skip spectra with too few orders            if flux_orders.shape[0] <= 38:                print("Skipping spectrum (not a TRES spectrum)")                continue            li_order = 38            flux = flux_orders[li_order]            wavelengths = np.linspace(6646, 6779, len(flux))            hdul.close()            if np.max(wavelengths) < 6715 or np.min(wavelengths) > 6700:                print("Skipping spectrum (no Li coverage)")                continue            m = 0            n = 0            for i in range(len(wavelengths)):                if wavelengths[i] > 6700:                    break                else:                    m += 1            for i in range(len(wavelengths)):                if wavelengths[i] > 6715:                    break                else:                    n += 1            if n - m <= 5:                print("Skipping spectrum (not enough Li points)")                continue            noisewave = np.zeros(n-m)            noiseflux = np.zeros(n-m)            for i in range(m, n):                noisewave[i-m] = wavelengths[i]                noiseflux[i-m] = flux[i]            def linear_func(x, m, b):                return m * x + b            params, covariance = curve_fit(linear_func, noisewave, noiseflux)            m_fit, b_fit = params            stdev = np.zeros(n-m)            for i in range(n-m):                stdev[i] = (noiseflux[i] - (m_fit * noisewave[i] + b_fit))**2            standard_deviation = (np.sum(stdev) / len(stdev))**0.5            individualSTDev = np.zeros(n-m)            for i in range(n-m):                individualSTDev[i] = noiseflux[i] / standard_deviation            SNR = np.sum(individualSTDev) / (n-m)            print("Li SNR:", SNR)            results.append({                "target": target,                "spectrum_file": file,                "Li_SNR": SNR            })                     df = pd.DataFrame(results)df.to_csv("Li_SNR_results.csv", index=False)print("Saved Li SNR results to Li_SNR_results.csv")